import { LogicWrapper, MakeLogicType, afterMount, connect, kea, key, path, props, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { Scene } from 'scenes/sceneTypes'
import { teamLogic } from 'scenes/teamLogic'

import { Breadcrumb } from '~/types'

import { platformAlertsRetrieve } from './generated/api'
import { PlatformAlertConfigurationApi } from './generated/api.schemas'
import { PLATFORM_ALERTS_BREADCRUMB } from './platformAlertsLogic'

export interface PlatformAlertLogicProps {
    id: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface platformAlertLogicValues {
    currentTeamId: number | null // teamLogic
    breadcrumbs: Breadcrumb[]
    configuration: PlatformAlertConfigurationApi | null
    configurationError: boolean
    configurationLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface platformAlertLogicActions {
    loadConfiguration: () => any
    loadConfigurationFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadConfigurationSuccess: (
        configuration: PlatformAlertConfigurationApi | null,
        payload?: any
    ) => {
        configuration: PlatformAlertConfigurationApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface platformAlertLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        breadcrumbs: (configuration: PlatformAlertConfigurationApi | null, arg: any) => Breadcrumb[]
    }
}

export type platformAlertLogicType = MakeLogicType<
    platformAlertLogicValues,
    platformAlertLogicActions,
    PlatformAlertLogicProps,
    platformAlertLogicMeta
>

export const platformAlertLogic: LogicWrapper<platformAlertLogicType> = kea<platformAlertLogicType>([
    props({} as PlatformAlertLogicProps),
    key((props) => props.id),
    path((key) => ['products', 'alerts_platform', 'frontend', 'platformAlertLogic', key]),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values, props }) => ({
        configuration: [
            null as PlatformAlertConfigurationApi | null,
            {
                loadConfiguration: async () => {
                    if (!values.currentTeamId) {
                        return null
                    }
                    return await platformAlertsRetrieve(String(values.currentTeamId), props.id)
                },
            },
        ],
    })),
    reducers({
        configurationError: [
            false,
            {
                loadConfiguration: () => false,
                loadConfigurationFailure: () => true,
            },
        ],
    }),
    selectors({
        breadcrumbs: [
            (s) => [s.configuration, (_, props) => props.id],
            (configuration: PlatformAlertConfigurationApi | null, id: string): Breadcrumb[] => [
                PLATFORM_ALERTS_BREADCRUMB,
                {
                    key: [Scene.PlatformAlert, id],
                    name: configuration?.name ?? 'Alert',
                },
            ],
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadConfiguration()
    }),
])
